export const getRuntimeKey = (): Runtime => {
  const userAgentSupported = typeof navigator !== 'undefined' && typeof navigator.userAgent === 'string'
  if (userAgentSupported) {
    for (const [runtimeKey, userAgent] of Object.entries(knownUserAgents)) {
      if (checkUserAgentEquals(userAgent)) return runtimeKey as Runtime
    }
  }
  if (typeof global?.EdgeRuntime === 'string') return 'edge-light'
  if (global?.fastly !== undefined) return 'fastly'
  if (global?.process?.release?.name === 'node') return 'node'
  return 'other'
}

export const combineBeforeRequestHooks = (
  hooks: BeforeRequestHook | BeforeRequestHook[]
): BeforeRequestHook => {
  if (!Array.isArray(hooks)) { return hooks }
  return async (req: Request): Promise<Request | false> => {
    let currentReq = req
    for (const hook of hooks) {
      const result = await hook(currentReq)
      if (result === false) return false
      if (result instanceof Request) currentReq = result
    }
    return currentReq
  }
}

export const mergePath = (base: string, path: string) => {
  let end = base.length
  while (base[end - 1] === '/') { end-- }
  path = path.replace(/^\/+/, '')
  return base.slice(0, end) + '/' + path
}
